workedExamples.solution_text:
The line crosses both axes at the origin. At this point, $x=0$ and $y=0$.

$x$-intercept: $(0,0)$.

$y$-intercept: $(0,0)$.
[tikz]
\begin{tikzpicture}[x=8mm,y=8mm,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\definecolor{lineblue}{HTML}{268CFF}
\definecolor{gridgrey}{HTML}{CCCCCC}
\draw[color=gridgrey,xstep=8mm,ystep=8mm] (-2,-2) grid (2,2);
\draw[<->,black] (-2.3,0)--(2.3,0) node[right] {$x$};
\draw[<->,black] (0,-2.3)--(0,2.3) node[above] {$y$};
\foreach \v in {-2,-1,1,2}{\draw[black] (\v,0.08)--(\v,-0.08);\node[below,font=\fontsize{8.5}{10}\selectfont] at (\v,-0.08) {$\v$};\draw[black] (0.08,\v)--(-0.08,\v);\node[left,font=\fontsize{8.5}{10}\selectfont] at (-0.08,\v) {$\v$};}
\draw[thick,<->,color=lineblue] (-1.8,1.8)--(1.8,-1.8);
\fill[color=lineblue] (0,0) circle (2pt);
\node[above right,xshift=3pt,yshift=3pt] at (0,0) {$(0,0)$};
\end{tikzpicture}
[/tikz]
